const D = { density:.5, relief:.55, energy:.6, scale:1, hue:282, speed:1, x:.5, y:.5, style:'gem', act:'drift', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v)), frc=v=>v-Math.floor(v), TAU=Math.PI*2;
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width,H=height,u=Math.min(W,H);
const style=P.style, wire=style==='wireframe', stained=style==='stained', lowp=style==='lowpoly';
const dens=clp(P.density,0,1), relief=clp(P.relief,0,1), en=clp(P.energy,0,1);
const nCells=Math.round(14+dens*58);

// ---- reseed per section: geometry key folds section into the effective seed ----
const sec = Math.floor(K.section)||0;
const effSeed = (P.seed|0) + sec*101;
const gkey = W+'x'+H+':'+nCells+':'+effSeed;
if(S.gkey!==gkey){
  S.gkey=gkey;
  const hsh=i=>{const s=Math.sin(i*127.1+effSeed*311.7)*43758.5453;return s-Math.floor(s);};
  const cols=Math.max(2,Math.round(Math.sqrt(nCells*W/H))), rows=Math.max(2,Math.ceil(nCells/cols));
  const sites=[]; let idx=0;
  for(let r=0;r<rows && idx<nCells;r++)for(let c=0;c<cols && idx<nCells;c++){
    const jx=(hsh(idx*2+1)-.5)*0.92, jy=(hsh(idx*2+2)-.5)*0.92;
    sites.push([(c+0.5+jx)/cols*W,(r+0.5+jy)/rows*H,hsh(idx*3+7)]); idx++;
  }
  const cells=[];
  for(let i=0;i<sites.length;i++){
    let poly=[[0,0],[W,0],[W,H],[0,H]];
    const px=sites[i][0], py=sites[i][1];
    for(let j=0;j<sites.length && poly.length;j++){
      if(j===i)continue;
      const qx=sites[j][0], qy=sites[j][1];
      const mx=(px+qx)/2, my=(py+qy)/2, nx=px-qx, ny=py-qy;
      const out=[];
      for(let k=0;k<poly.length;k++){
        const Aa=poly[k], Bb=poly[(k+1)%poly.length];
        const dA=(Aa[0]-mx)*nx+(Aa[1]-my)*ny;
        const dB=(Bb[0]-mx)*nx+(Bb[1]-my)*ny;
        if(dA>=0) out.push(Aa);
        if((dA>=0)!==(dB>=0)){ const t=dA/(dA-dB); out.push([Aa[0]+t*(Bb[0]-Aa[0]),Aa[1]+t*(Bb[1]-Aa[1])]); }
      }
      poly=out;
    }
    if(poly.length>=3){
      let cx=0,cy=0; for(const v of poly){cx+=v[0];cy+=v[1];} cx/=poly.length; cy/=poly.length;
      cells.push({v:poly,cx,cy,ph:sites[i][2],hj:sites[i][2]-0.5});
    }
  }
  S.cells=cells;
}
const cells=S.cells||[];

// ---- drifting light (real-time motion floor, never rephases) ----
let actLmul=1, actH=1, actJit=0;
if(P.act==='shatter'){ actLmul=1.9; actH=1.35; actJit=0.5; }
else if(P.act==='grow'){ actH=0.45+0.9*frc(K.section/8+K.t*0.01); }
const laz=K.t*0.17*(0.5+P.speed*0.7)*actLmul + (P.x-0.5)*3.0;
const lel=0.55+0.28*Math.sin(K.t*0.083)+(P.y-0.5)*0.5;
let Lx=Math.cos(laz)*Math.cos(lel), Ly=Math.sin(laz)*Math.cos(lel), Lz=Math.sin(lel)+0.35;
{ const ll=Math.hypot(Lx,Ly,Lz)||1; Lx/=ll; Ly/=ll; Lz/=ll; }
const hBase=u*(0.035+relief*0.24)*actH;
const intens=0.65+0.55*K.intensity;

// ---- background ----
const bgH=((P.hue%360)+360)%360;
if(wire){ background(bgH,55,6); }
else if(stained){ background(bgH,30,4); }
else { background(bgH,lowp?18:44,lowp?12:7); }

noStroke();
for(let ci=0;ci<cells.length;ci++){
  const cell=cells[ci], v=cell.v, n=v.length, cx=cell.cx, cy=cell.cy;
  // per-cell beat breathe (staggered so field never re-aligns as one flash)
  const cph=frc(K.beat*0.5*P.speed+cell.ph);
  const pop=Math.pow(1-cph,2.3);
  const jit=actJit? (frc(cell.ph*13.7+K.beat*0.25)-0.5)*u*0.02*actJit*en : 0;
  const h=hBase*(0.45+0.75*pop+A.bass*1.15)*intens;
  const cellH=(bgH+cell.hj*46+K.t*4)%360;

  if(stained){
    // flat translucent jewel cell, thick dark leading, backlit — mass + lead, no facets
    const lit=clp(0.42+0.5*Math.sin(cell.ph*TAU+laz)+0.4*K.swell+A.bass*0.5,0.12,1);
    fill((cellH+360)%360, 58+22*en, 30+58*lit, 92);
    beginShape(); for(let k=0;k<n;k++) vertex(v[k][0],v[k][1]); endShape(CLOSE);
    continue;
  }

  // faceted pyramid: apex above centroid, fan of lit triangles
  for(let k=0;k<n;k++){
    const a=v[k], b=v[(k+1)%n];
    const e1x=a[0]-cx, e1y=a[1]-cy, e1z=-h;
    const e2x=b[0]-cx, e2y=b[1]-cy, e2z=-h;
    let nx=e1y*e2z-e1z*e2y, ny=e1z*e2x-e1x*e2z, nz=e1x*e2y-e1y*e2x;
    if(nz<0){ nx=-nx; ny=-ny; nz=-nz; }
    const nl=Math.hypot(nx,ny,nz)||1;
    const diff=(nx*Lx+ny*Ly+nz*Lz)/nl;
    const lit=clp(0.5+0.5*diff,0,1);
    if(wire){
      const g=clp(0.15+0.85*lit,0,1);
      stroke((cellH+360)%360, 70-40*g, 40+60*g, 30+65*g);
      strokeWeight(1+1.4*g*en);
      line(cx+jit,cy+jit,a[0]+jit,a[1]+jit);
    } else {
      const spec=lowp?0:Math.pow(clp(diff,0,1),22)*95*en;
      const sat=(lowp?24+18*en:62+30*en)*(1-Math.min(0.85,spec/110));
      const bri=(lowp?34+50*lit:16+72*lit)+spec;
      fill((cellH+360)%360, clp(sat,0,100), clp(bri,0,100));
      triangle(cx+jit,cy+jit,a[0]+jit,a[1]+jit,b[0]+jit,b[1]+jit);
    }
  }
  // cut-gem facet edges / stained leading handled below per style
  if(!wire && !lowp){
    noFill(); stroke(bgH,40,4,55); strokeWeight(u*0.0016);
    beginShape(); for(let k=0;k<n;k++) vertex(v[k][0],v[k][1]); endShape(CLOSE);
    noStroke();
  }
}

// stained: heavy leading pass over the whole partition
if(stained){
  noFill(); stroke(bgH,45,2,96); strokeWeight(u*0.006*(0.8+0.4*K.swell));
  for(const cell of cells){ const v=cell.v; beginShape(); for(let k=0;k<v.length;k++) vertex(v[k][0],v[k][1]); endShape(CLOSE); }
  // soft backlight bloom on the beat
  blendMode(ADD); noStroke();
  const gl=18+30*K.pulse+A.bass*40;
  fill(((bgH+40)%360),50,90,clp(gl*0.12,0,26));
  rect(0,0,W,H);
  blendMode(BLEND);
}

// specular sparkle on strongest-lit apexes (gem only) — tiny, adds live shimmer
if(!wire && !stained && !lowp && en>0.15){
  blendMode(ADD); noStroke();
  const spark=clp(K.pulse*0.8+A.treble*1.2,0,1);
  if(spark>0.05){
    for(let ci=0;ci<cells.length;ci+=3){
      const cell=cells[ci];
      const sz=u*0.012*(0.5+spark);
      fill(50,10,100,clp(40*spark,0,55));
      circle(cell.cx,cell.cy,sz);
    }
  }
  blendMode(BLEND);
}

blendMode(BLEND); drawingContext.shadowBlur=0; noStroke();
